+        GEMM_FMA_ROW(c0, 0);
+        GEMM_FMA_ROW(c1, 1);
+        GEMM_FMA_ROW(c2, 2);
+        GEMM_FMA_ROW(c3, 3);
+        GEMM_FMA_ROW(c4, 4);
+        GEMM_FMA_ROW(c5, 5);
+        GEMM_FMA_ROW(c6, 6);
+        GEMM_FMA_ROW(c7, 7);
+    }
