+    for (int r = 0; r < rows; ++r) {
+        for (int x = 0; x < cols; ++x) {
+            sums[r][x] = accumulate ? c[static_cast<std::size_t>(r) * ldc + x] : 0.0f;
+        }
+    }
+
+    for (int k = 0; k < kc; ++k) {
+        const float* brow = b + static_cast<std::size_t>(k) * bstride;
+        for (int r = 0; r < rows; ++r) {
+            const float av = a[static_cast<std::size_t>(r) * lda + k];
+            for (int x = 0; x < cols; ++x) {
+                sums[r][x] += av * brow[x];
+            }
+        }
+    }
+
+    for (int r = 0; r < rows; ++r) {
